import { ListFilterIcon, SearchIcon } from 'lucide-react';
import type { ReactNode } from 'react';
import { activeFilters, applyFilters, FilterChips } from '@/components/company-os/filter-chips';
import type { FilterState } from '@/components/company-os/filter-chips';
import { FilterControl } from '@/components/company-os/filter-control';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';

export type FilterBarLabels = { filters: string; clearFilters: string; search: string };

const defaultLabels: FilterBarLabels = { filters: 'Filters', clearFilters: 'Clear filters', search: 'Search' };

export function FilterBar({
    state,
    end,
    labels = defaultLabels,
}: {
    state: FilterState;
    end?: ReactNode;
    labels?: FilterBarLabels;
}) {
    const inline = state.fields.filter((field) => field.inline);
    const overflow = state.fields.filter((field) => !field.inline);
    const overflowKeys = overflow.map((field) => field.key);
    const overflowActive = activeFilters(state).filter((filter) => overflowKeys.includes(filter.key)).length;

    return (
        <div className="grid gap-3">
            <div className="flex flex-wrap items-center gap-2">
                {state.searchPlaceholder && (
                    <div className="relative w-full sm:w-56">
                        <SearchIcon className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-slate-400" />
                        <Input
                            aria-label={labels.search}
                            className="pl-9"
                            placeholder={state.searchPlaceholder}
                            defaultValue={state.filters.search ?? ''}
                            onKeyDown={(event) =>
                                event.key === 'Enter' && applyFilters(state, { search: event.currentTarget.value })
                            }
                        />
                    </div>
                )}
                {inline.map((field) => (
                    <FilterControl key={field.key} field={field} state={state} className="w-36 shrink-0" />
                ))}
                {overflow.length > 0 && (
                    <Popover>
                        <PopoverTrigger asChild>
                            <Button variant="outline" className="shrink-0">
                                <ListFilterIcon />
                                {labels.filters}
                                {overflowActive > 0 && (
                                    <span className="rounded-full bg-primary/10 px-1.5 text-xs text-primary tabular-nums">
                                        {overflowActive}
                                    </span>
                                )}
                            </Button>
                        </PopoverTrigger>
                        <PopoverContent className="grid gap-3">
                            {overflow.map((field) => (
                                <div key={field.key} className="grid gap-1.5">
                                    <Label className="font-light">{field.label}</Label>
                                    <FilterControl field={field} state={state} />
                                </div>
                            ))}
                        </PopoverContent>
                    </Popover>
                )}
                {end && <div className="flex flex-wrap items-center gap-2 lg:ml-auto">{end}</div>}
            </div>
            <FilterChips state={state} className="justify-start" clearLabel={labels.clearFilters} />
        </div>
    );
}

import { XIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { navigateWithQuery } from '@/lib/navigation';
import { cn } from '@/lib/utils';

export type Option = { value: string; label: string };

export type FilterField = {
    key: string;
    label: string;
    options?: Option[];
    placeholder?: string;
    defaultValue?: string;
    inline?: boolean;
    searchable?: boolean;
    text?: boolean;
};

export type FilterState = {
    url: string;
    filters: Record<string, string>;
    fields: FilterField[];
    searchPlaceholder?: string;
};

export type ActiveFilter = { key: string; label: string };

export function applyFilters(
    { url, filters }: Pick<FilterState, 'url' | 'filters'>,
    changes: Record<string, string>,
) {
    const query = Object.fromEntries(
        Object.entries({ ...filters, ...changes }).filter(([, value]) => value !== ''),
    );

    navigateWithQuery(url, query, { preserveState: true, preserveScroll: true, replace: true });
}

export function activeFilters({ filters, fields }: FilterState): ActiveFilter[] {
    const search = filters.search ? [{ key: 'search', label: `“${filters.search}”` }] : [];

    return [
        ...search,
        ...fields.flatMap((field) => {
            const value = filters[field.key] ?? '';

            if (value === '' || value === (field.defaultValue ?? '')) {
                return [];
            }

            const option = field.options?.find((choice) => choice.value === value);

            return [{ key: field.key, label: `${field.label}: ${option?.label ?? value}` }];
        }),
    ];
}

export function FilterChips({
    state,
    className,
    clearLabel = 'Clear filters',
}: {
    state: FilterState;
    className?: string;
    clearLabel?: string;
}) {
    const active = activeFilters(state);

    if (active.length === 0) {
        return null;
    }

    const clearAll = Object.fromEntries(
        [...state.fields.map((field) => field.key), 'search'].map((key) => [key, '']),
    );

    return (
        <div className={cn('flex flex-wrap items-center justify-center gap-2', className)}>
            {active.map((filter) => (
                <span
                    key={filter.key}
                    className="inline-flex items-center gap-1 rounded-full bg-primary/10 py-0.5 pr-1 pl-2.5 text-xs font-medium text-primary"
                >
                    {filter.label}
                    <button
                        type="button"
                        aria-label={`Remove ${filter.label}`}
                        className="rounded-full p-0.5 hover:bg-primary/15"
                        onClick={() => applyFilters(state, { [filter.key]: '' })}
                    >
                        <XIcon className="size-3" />
                    </button>
                </span>
            ))}
            <Button variant="outline" size="sm" className="h-6 px-2 text-xs" onClick={() => applyFilters(state, clearAll)}>
                {clearLabel}
            </Button>
        </div>
    );
}

import { applyFilters } from '@/components/company-os/filter-chips';
import type { FilterField, FilterState } from '@/components/company-os/filter-chips';
import { Combobox } from '@/components/ui/combobox';
import { Input } from '@/components/ui/input';
import { OptionSelect } from '@/components/ui/option-select';

export function FilterControl({
    field,
    state,
    className,
}: {
    field: FilterField;
    state: FilterState;
    className?: string;
}) {
    const value = state.filters[field.key] ?? field.defaultValue ?? '';
    const set = (next: string) => applyFilters(state, { [field.key]: next });

    if (field.text) {
        return (
            <Input
                aria-label={field.label}
                placeholder={field.placeholder}
                defaultValue={value}
                className={className}
                onKeyDown={(event) => event.key === 'Enter' && set(event.currentTarget.value)}
            />
        );
    }

    return field.searchable ? (
        <Combobox
            aria-label={field.label}
            placeholder={field.placeholder}
            options={field.options ?? []}
            value={value}
            onValueChange={set}
            className={className}
        />
    ) : (
        <OptionSelect
            aria-label={field.label}
            placeholder={field.placeholder}
            options={field.options ?? []}
            value={value}
            onValueChange={set}
            className={className}
        />
    );
}
